INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (501, 'Hotel', 'PrivateTransfer', 'PrivateTransfer', NULL, NULL, NULL, 'Ateshgah - Fire Temple Tour (ENTRANCE) \n   (Fire temple was firmly established by the time of the  \n   Parthian Empire (247 BCE - 224 CE) and reached  \n   their height of sophistication in the time of the  \n   Sassanian Empire (224-651 CE). After the fall of  \n   the Sassanians to the Muslim Arab Invasion of 651 CE,  \n   fire temples were destroyed or converted into mosques. \n   Zoroastrians are said to have kept some of the flames  \n   from these temples burning in secret, however, and these were used to light the fires in later temples, notably those of the Parsees of India who preserved the Zoroastrian traditions and established fire temples later in that country. + A 10 m long wall of fire is never extinguishing.  \n   It is burning continuously alongside the edge of the hill.  \n   The scene is naturally is at its most spectacular at night.  \n   The height of the flames changes, but in some moments \n   it reach to 3 meters (9.8 ft) from the ground. Yanar Dag  \n   is now a protected site and there are extensive archaeological studies are going on. Local lore states that it was a shepherd that accidentally ignited the fire in the 1950s by tossing a cigarette, and that it has burnt ever since.)', 29.0, 32.0, 29.0, 31.0, 118.0, 147.0, 177.0, 206.0, 206.0, 12.0, 47.0);
