INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (567, 'Airport', 'PrivateTransfer', 'PrivateTransfer', NULL, NULL, NULL, 'Panoramic City Tour starts with panoramic full evening city view of Baku followed by: \n    \n   -Highland Park (Which is the highest point in the Azerbaijani capital,  \n   opening a panoramic view of the city and its bay. The city''s residents \n   and visitors often come here to see a bird''s eye view of Baku, and  \n   just have a walk. The Upland Park can be reached by cable railway  \n   (funicular) in 7-8 minutes from the boulevard or by climbing up the \n   endless stone stairs.) \n    \n   -Flame Towers (The city''s tallest building. The height of 182 m.  \n   Flame Towers - consisting of three high-rise buildings in the complex.)', 30.0, 30.0, 36.0, 48.0, 124.0, 147.0, 177.0, 206.0, 206.0, 12.0, 47.0);
