INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (707, 'Hotel', 'PrivateTransfer', 'PrivateTransfer', NULL, NULL, NULL, 'Nizami Street in Baku is an absolute must-visit! The vibrant atmosphere, beautifully lit streets, and a mix of modern and historic architecture create an unforgettable experience. Itâ$™s perfect for a leisurely stroll, shopping at high-end boutiques, or enjoying a meal at one of the many cafes and restaurants. The street truly comes alive in the evening, with its lively vibe and gorgeous lighting. Whether youâ$™re a tourist or a local, Nizami Street offers something for everyone. +                  Old City tour starts from Shamakhi Gates followed by Old city below places (Photo stop) -Shamakhi Gates -Sculptures of Azim Azimzadehâ$™s -Caravanserai of Bukhara -Caravanserai of Multani -Maidenâ$™s Tower -Bazar Square -Miniature Booksâ$™ Museum -Shirvanshahsâ$™ Palace + Walking tour starts along the Baku Boulevard followed by: -Mini Venice of Baku \n   -Carpet Museum -Deniz Mall  \n   -Ferries Wheel ride  \n   -Carpet Museums \n   -Boat cruise  \n   -Cristal Hall \n   -Biking Area       +     Visit to Heydar Aliyev Center for PHOTO SHOOTING  \n   & â$œI LOVE BAKUâ$ sign for PHOTOSTOP \n   (If itâ$™s first time of your arrival to Baku, just be aware of  \n   that from the bird view you can clearly see the Heydar  \n   Aliyevâ$™s Signature on the Heydar Aliyevâ$™s Center design.  \n   Itâ$™s a wave-like building rises from a bed of concrete. \n   Its immobile white walls look as though they have been  \n   frozen mid-ripple. The abstract architecture is unlike anything  \n   else in the capital city. The Heydar Aliyev Center, which was  \n   designed by renowned architect Zaha Hadid.)', 35.0, 38.0, 40.0, 50.0, 88.0, 147.0, 177.0, 206.0, 206.0, 12.0, 47.0);
