INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (723, 'Baku', 'Day Trip', 'Day Trip', NULL, NULL, NULL, 'Baku to Guba to Baku (Same Day) Guba and visiting the Guba Genocide  \n   Memorial Complex. \n   The mass grave, discovered accidentally during the  \n   excavations for construction purposes in the town of Guba  \n   in 2007, was a clear evidence of the genocide of the Muslim  \n   population of Guba, committed by Armenian armed forces  \n   under Bolshevik name in May 1918. The area is wonderful  \n   on the left side of river Qudiyal-chay. Here you can see the  \n   part of history of our nation and relax with nature. \n   Visiting Qecresh Forest  \n  Qechresh Forest, also known as Gachresh Forest, is one of the largest forests in Azerbaijan, located near the town of Quba. Renowned for its dense foliage and majestic landscape, it features a rich biodiversity and is a habitat for various plant species and wildlife. The forest''s high altitude and clean, fresh air make it a perfect spot for those looking for outdoor adventures or simply to relax .', 71.0, 76.0, 80.0, 85.0, 195.0, 265.0, 324.0, 354.0, 354.0, 12.0, 47.0);
INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (724, 'Baku', 'Overnight', 'Overnight', NULL, NULL, NULL, 'Baku to Guba to Baku (1 Night Stay in Guba) Reaching to Guba and visiting the Guba Genocide  \n   Memorial Complex. \n   The mass grave, discovered accidentally during the  \n   excavations for construction purposes in the town of Guba  \n   in 2007, was a clear evidence of the genocide of the Muslim  \n   population of Guba, committed by Armenian armed forces  \n   under Bolshevik name in May 1918. The area is wonderful  \n   on the left side of river Qudiyal-chay. Here you can see the  \n   part of history of our nation and relax with nature. \n   Visiting Qecresh Forest  \n  Qechresh Forest, also known as Gachresh Forest, is one of the largest forests in Azerbaijan, located near the town of Quba. Renowned for its dense foliage and majestic landscape, it features a rich biodiversity and is a habitat for various plant species and wildlife. The forest''s high altitude and clean, fresh air make it a perfect spot for those looking for outdoor adventures or simply to relax .', 107.0, 112.0, 116.0, 121.0, 255.0, 353.0, 474.0, 560.0, 560.0, 30.0, 65.0);
INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (725, 'Baku', 'Day Trip', 'Day Trip', NULL, NULL, NULL, 'Baku to Shahdag to Baku (Same Day) visit Shahdag Mountains  \n  ( Shahdag is the highest part of the side ridge in the territory of the Republic of Azerbaijan. It is separated from the Kyzylgaya plateau by the Gusar river valley. composed of sediments of the Jurassic and Cretaceous systems. Its height is up to 4243 meters (Shahdag peak). There are alpine and subalpine meadows, glaciers with an area of more than 1 square km.) \n  Discover the wonders of Shahdag, a land of ancient glaciers, majestic valleys, and stunning mountain lakes! Designed with avid outdoor enthusiasts in mind, Shahdag Mountain Resort offers an array of thrilling activities throughout the year. Picture yourself zooming down the slopes, feeling the crisp mountain air on your face as you carve your way through powdery snow. And for those seeking an adrenaline rush of a different kind, don''t miss the Shahdag Coaster, an exhilarating roller coaster that takes you on a wild ride through the breathtaking mountain scenery.', 71.0, 76.0, 80.0, 85.0, 195.0, 265.0, 324.0, 354.0, 354.0, 12.0, 47.0);
INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (726, 'Baku', 'Overnight', 'Overnight', NULL, NULL, NULL, 'Baku Hotel to Shahdag (1 Night stay) to Baku Hotel -visit Shahdag Mountains  \n  ( Shahdag is the highest part of the side ridge in the territory of the Republic of Azerbaijan. It is separated from the Kyzylgaya plateau by the Gusar river valley. composed of sediments of the Jurassic and Cretaceous systems. Its height is up to 4243 meters (Shahdag peak). There are alpine and subalpine meadows, glaciers with an area of more than 1 square km.) \n  Discover the wonders of Shahdag, a land of ancient glaciers, majestic valleys, and stunning mountain lakes! Designed with avid outdoor enthusiasts in mind, Shahdag Mountain Resort offers an array of thrilling activities throughout the year. Picture yourself zooming down the slopes, feeling the crisp mountain air on your face as you carve your way through powdery snow. And for those seeking an adrenaline rush of a different kind, don''t miss the Shahdag Coaster, an exhilarating roller coaster that takes you on a wild ride through the breathtaking mountain scenery.', 107.0, 112.0, 116.0, 121.0, 255.0, 353.0, 474.0, 560.0, 560.0, 30.0, 65.0);
INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (727, 'Baku', 'Day Trip', 'Day Trip', NULL, NULL, NULL, 'Baku Hotel to Shahdag + Candy Cane Mountain Visit to Baku Hotel Candy Cane Mountains are a psychedelic, red-pink and white striped area of exposed rock in the Northwest of Azerbaijan. Iron in the ground gives the mountains their deep red color and powdery shale makes up the white parts. Through a geological process, they’ve mixed together underground, layer on top of layer, and when exposed to the elements, they eroded into a beautiful, completely bizarre sight', 71.0, 78.0, 82.0, 88.0, 230.0, 312.0, 383.0, 427.0, 427.0, 12.0, 47.0);
