INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (729, 'Baku', 'Day Trip', 'Day Trip', NULL, NULL, NULL, 'Baku to Gabala to Baku (Same Day) visit Tufandag Mountains \n  (Tufandagh is a mountain peak of the Greater Caucasus range,  \n  located in the Qusar District of Azerbaijan. With an elevation of  \n  4,191 metres (13,750 ft) above sea level, it third highest mountain  \n  in Azerbaijan). Visit to Nohur lake, guests enjoy with Panoramic Nature view (Located about 5 km. east of the Gabala city, the lake is surrounded by the forests and high mountains called Yumru, Goydag and Gulluburun. The lake covers 240 ha in total and has the maximum depth of 24 meters. The Nohur lake has very clear water thanks to the fresh water sources spilt into the lake. Apart from the small seasonal water supply coming from the mountains of Caucasus, Damiraparan and Vandam rivers also flow to the lake.)', 71.0, 76.0, 80.0, 85.0, 195.0, 295.0, 354.0, 412.0, 412.0, 12.0, 47.0);
