INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (743, 'Baku', 'Day Trip', 'Day Trip', NULL, NULL, NULL, 'Baku to Sheki to Gobusthan to Baku (Same Day) Church of Kish \n  (Kish is one of the oldest villages in present-day Azerbaijan, and is well-known for a church here, during the period of Caucasian Albania. The current building of the temple of Saint Elisha was built in the 10-12th centuries. According to some scholars’ opinions, the church in Kish stands on the same place where St. Elisha founded his own church. That is why the temple in Kish is often referred to as one of the oldest spiritual centers in the Caucasus, since St. Elisha was the first patriarch of the Church of Caucasian Albania and an early Christian leader in the Caucasus.) SHEKI FORTRESS. The Sheki fortress was built to protect the historic center that is now a UNESCO World Heritage site. The original walls were 8 meters high and 2 meters thick with several defensive towers and arched gateways. Unfortunately, most of the fortress was destroyed, although some parts have been restored. SHEKI KARAVAN SERAY The Karavan Seray hotel, it is one of the top things to do in Sheki. Caravanserais along thje silk road provided a secure place to sleep for merchants passing through with their camels and donkeys. TASTING SHEKI HALVA The great food in Sheki was not restricted to the market and trying some of the local delicacies is one of the great things to do in Sheki. In the Caucasus it becomes difficult to keep track of all the great food experiences you will have, but Sheki Halva makes it high up the list + Gobustan National Park Museum followed by Gobustan Petroglyph Rock Art Cultural Landscape Rock paintings of Gobustan were first discovered in 1939 by archaeologist I. Jafarzade. On this territory there are many traces of primitive inhabitance of people belong tothe period of the Paleolithic and Mesolithic. Rock engravings Gobusta cover a long historical period nearly 15,000 years. In the Gobustan can be found rock paintings created in the primitive epoch and up to the Middle Ages, nowadays there are about 6,000 drawings. The territory of Gobustan had favorable living conditions in the Mesolithic, Neolithic and Bronze Age and was inhabited by hunters and fishermen. Petroglyphs of theGobustan museum included to the UNESCO World Heritage List. + Old City tour starts from Shamakhi Gates followed by Old city below places (Photo stop)', 77.0, 83.0, 101.0, 112.0, 300.0, 207.0, 412.0, 471.0, 471.0, 12.0, 47.0);
