INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (760, 'Hotel', 'PrivateTransfer', 'PrivateTransfer', NULL, NULL, NULL, 'Gobustan National Park Museum followed by Gobustan Petroglyph Rock Art Cultural Landscape \n   Rock paintings of Gobustan were first discovered in 1939  \n   by archaeologist I. Jafarzade. On this territory there are  \n   many traces of primitive inhabitance of people belong to \n   the period of the Paleolithic and Mesolithic. Rock  \n   engravings of Gobustan cover a long historical period  \n   nearly 15,000 years. In the Gobustan can be found rock \n   paintings created in the primitive epoch and up to the  \n   Middle Ages, nowadays there are about 6,000 drawings.  \n   The territory of Gobustan had favorable living conditions  \n   in the Mesolithic, Neolithic and Bronze Age and was \n   inhabited by hunters and fishermen. Petroglyphs of the \n   Gobustan museum included to the UNESCO World Heritage List. + Old City tour starts from Shamakhi Gates followed by Old city below places (Photo stop) \n   -Shamakhi Gates \n   -Sculptures of Azim Azimzadeh \n   -Caravanserai of Bukhara \n   -Caravanserai of Multani \n   -Maiden Tower \n   -Bazar Square \n   -Miniature Books Museum \n   -Shirvanshahs Palace', 41.0, 47.0, 47.0, 59.0, 130.0, 147.0, 177.0, 206.0, 206.0, 12.0, 47.0);
