INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (865, 'Baku', 'Day Trip', 'Day Trip', NULL, NULL, NULL, 'Baku Hotel to Shahdag + Candy Cane Mountain Visit to Baku Hotel Candy Cane Mountains are a psychedelic, red-pink and white striped area of exposed rock in the Northwest of Azerbaijan. Iron in the ground gives the mountains their deep red color and powdery shale makes up the white parts. Through a geological process, they’ve mixed together underground, layer on top of layer, and when exposed to the elements, they eroded into a beautiful, completely bizarre sight', 71.0, 78.0, 82.0, 88.0, 230.0, 312.0, 383.0, 427.0, 427.0, 12.0, 47.0);
