INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (884, 'Baku', 'Day Trip', 'Day Trip', NULL, NULL, NULL, 'Baku to Ganja to Baku (Same Day) Visiting the Nizami Ganjavi Mausoleum \n  As one of Ganja’s most prestigious historical sites, the mausoleum complex of the superb Azerbaijani poet Nizami Ganjavi is one of the city’s most worthwhile places to visit. The mausoleum was restored in 1990-1991, giving it the status of a protected complex. In the lower part within the monument, you can find the poet’s crypt. In front of the mausoleum, there is a square adorned with fantastic creatures symbolising Nizami''s ‘Khamsa,’ where visitors can stroll, take pictures to share and enjoy spectacular views of the city of Ganja. \n  In front of Nizami''s mausoleum is Nizami Ganjavi Museum, where books and monographs are on display, published for commemoration jubilees of the poet’s birthday. Moreover, the museum showcases originals and copies of rare manuscripts and miniatures of Nizami''s Khamsa, preserved in national libraries in Austria, Russia, Germany, the United Kingdom, the Library of Alexandria in Egypt, the Strasbourg Central Library in France and the Metropolitan Museum in the United States. The museum also has a conference hall for educational events, which is open to visitors interested in cultural and scientific activities in Ganja.Visiting Javad Khan Street.This street, one of the most central and longest in Ganja, is named after Ganja''s last khan, Javad Khan. It is one of the most visited and beautiful places in Ganja among both locals and foreign tourists. The architectural heritage of Ganja, characterised by red brickwork, has been characteristic of this street for centuries. Even in renovated buildings, ancient ornaments and patterns have been restored and emphasised, visi Nizami Ganjavi Square, visit Javad Khan Tomb. Ganja owes its current tranquillity to the raging battles and courageous fighters of the past. The memory of Javad Khan, who died defending his beloved Ganja in one of these struggles, lives on in Javad Khan Mausoleum – a fitting tribute erected over his grave.', 77.0, 83.0, 101.0, 112.0, 265.0, 354.0, 412.0, 471.0, 471.0, 12.0, 47.0);
