INSERT INTO transfers (duty_code, a, b, service, distance, start_time, duration_mins, day_schedule, sedan_4_local, sedan_4_english, vito_8_local, vito_8_english, sprinter_18, isuzu_27, merc_403_45, trivago_54, neoplan_48, guides_a, guides_o) VALUES (891, 'Gabala', 'Day Trip', 'Day Trip', NULL, NULL, NULL, 'Gabala to Sheki to Gabala (Same Day) Church of Kish \n  (Kish is one of the oldest villages in present-day Azerbaijan, and is well-known for a church here, during the period of Caucasian Albania. The current building of the temple of Saint Elisha was built in the 10-12th centuries. According to some scholars’ opinions, the church in Kish stands on the same place where St. Elisha founded his own church. That is why the temple in Kish is often referred to as one of the oldest spiritual centers in the Caucasus, since St. Elisha was the first patriarch of the Church of Caucasian Albania and an early Christian leader in the Caucasus.) SHEKI FORTRESS. The Sheki fortress was built to protect the historic center that is now a UNESCO World Heritage site. The original walls were 8 meters high and 2 meters thick with several defensive towers and arched gateways. Unfortunately, most of the fortress was destroyed, although some parts have been restored. SHEKI KARAVAN SERAY The Karavan Seray hotel, it is one of the top things to do in Sheki. Caravanserais along thje silk road provided a secure place to sleep for merchants passing through with their camels and donkeys. TASTING SHEKI HALVA The great food in Sheki was not restricted to the market and trying some of the local delicacies is one of the great things to do in Sheki. In the Caucasus it becomes difficult to keep track of all the great food experiences you will have, but Sheki Halva makes it high up the list', 30.0, 36.0, 47.0, 59.0, 100.0, 120.0, 147.0, 177.0, 177.0, 12.0, 47.0);
